get_shipping_settings.code:
import (
	"fmt"
)

resp, err := client.ShippingSettings().GetShippingSettings(ctx, nil, nil)
if err != nil {
	log.Fatal(err)
}
settings := resp.Map().(map[string]any)["shipping_settings"].(map[string]any)
fmt.Println(settings["apply_store_tax_settings_to_shipping"], settings["enable_shipping_class"], settings["enable_class_in_flat_view"])
if profile, ok := settings["default_shipping_profile"].(map[string]any); ok {
	fmt.Println(profile["id"], profile["name"])
}

